package com.bqsqwad.heartbreakhealer.feature.entertainment

/** Five additional complete ten-part stories. */
internal object StoryLibraryBatch8 {
    val stories = listOf(
        StorySeries("the_orange_roof", "The Orange Roof", "A neighbourhood's unusual rooftop becomes a shared learning space after its history is rediscovered.", listOf(
            StoryPart(1, "The Bright Roof", listOf("A new student, Kosi, noticed an orange roof above the old community centre. The building manager said it had once been a workshop for young inventors.", "A faded sign showed a sun symbol and the words 'Ideas belong to everyone'. Kosi wondered what had happened to the workshop.")),
            StoryPart(2, "The Workshop Register", listOf("The centre archive held a register of projects: simple radios, model bridges, paper kites, and recycled-art displays. The final page listed a public exhibition that never took place.", "A note said the exhibition was postponed because the roof needed repairs. Kosi asked the manager whether the building had been inspected since.")),
            StoryPart(3, "The Engineer's Visit", listOf("A retired engineer who had volunteered at the workshop visited the centre. He explained that the roof had been closed after a leak, but the indoor workshop had continued for a while.", "He remembered that the students had built a weather station and wanted to display its readings. The station might still be in storage.")),
            StoryPart(4, "A Box of Instruments", listOf("The caretaker found a box containing a rain gauge, a simple wind vane, and handwritten observation sheets. The instruments were dusty but labelled carefully.", "The engineer explained that any outdoor equipment would need a safe mounting plan and regular checks. The students began by studying the old data indoors.")),
            StoryPart(5, "The Roof Inspection", listOf("The centre arranged a professional roof inspection. The report identified repairs and confirmed that only a small designated section could be used after work was completed.", "Kosi's team redesigned the idea as a supervised learning corner, with no public access to restricted roof areas.")),
            StoryPart(6, "A New Weather Project", listOf("The science teacher helped students plan a small weather display using approved equipment and safe installation. They also prepared a backup indoor display for days when the roof could not be accessed.", "The old observation sheets revealed a pattern of rainfall that helped the students understand why the original project had mattered to local gardeners.")),
            StoryPart(7, "The Exhibition Returns", listOf("After repairs, the centre hosted an exhibition indoors. Students displayed the old instruments, the historical weather notes, and their new project plan.", "The retired engineer explained how the first workshop had encouraged young people to ask questions and test ideas responsibly.")),
            StoryPart(8, "The Orange Roof Opens", listOf("The centre manager approved limited supervised access to the designated learning corner. A clear schedule, safety rules, and maintenance responsibility were posted at the entrance.", "The students installed a small sign with the sun symbol, restoring the workshop's original identity without pretending the entire roof was open.")),
            StoryPart(9, "A Record of Every Reading", listOf("The weather project began collecting new observations. Students recorded dates and conditions consistently, and the teacher checked the equipment at regular intervals.", "The centre shared a monthly summary with local gardeners, who found the information useful for planning activities.")),
            StoryPart(10, "Ideas Belong to Everyone", listOf("At the end of the term, Kosi placed the old register beside the new weather log. The workshop had not returned exactly as it once was, but its spirit had survived.", "The orange roof became a symbol of careful curiosity: a place where ideas were welcomed, evidence mattered, and safety came before excitement. The old exhibition had finally taken place, the instruments had a purpose again, and the next group of students had a clear plan to continue."))
        )),
        StorySeries("the_hidden_garden_gate", "The Hidden Garden Gate", "A forgotten gate leads a student team to restore a shared path between two neighbourhoods.", listOf(
            StoryPart(1, "A Gate in the Ivy", listOf("While sketching plants for art class, Yemi spotted a narrow gate hidden behind ivy. It connected the school garden to a path that did not appear on the current map.", "The groundskeeper said the path had once joined two neighbourhood streets, but it was closed after the garden changed hands.")),
            StoryPart(2, "The Old Path Map", listOf("The school archive contained a hand-drawn map showing the path and a small resting place halfway along it. The map was signed by a local residents' group.", "Yemi asked the school manager whether the path could be reopened. The manager said ownership and access rights would need to be checked first.")),
            StoryPart(3, "The Residents' Group", listOf("A retired group secretary remembered the path as a shared route used by families walking to the library. She had kept meeting minutes about its maintenance.", "The minutes showed that the path was closed temporarily during construction, with an agreement to review access after the work finished.")),
            StoryPart(4, "The Unfinished Review", listOf("The council archive confirmed that the construction had ended, but the access review was never completed. The path had remained closed because nobody submitted the final inspection request.", "Yemi and the residents' group asked the council to inspect the route before anyone attempted to use it.")),
            StoryPart(5, "The Inspection", listOf("The council found that parts of the path needed resurfacing and the old gate required repair. A section near the resting place was not suitable for public access until drainage work was completed.", "The school and residents agreed to wait for the approved repairs and not bypass the closed section.")),
            StoryPart(6, "A Shared Design", listOf("The students proposed clear signs, a maintained surface, and a small garden beside the school entrance. The residents added a request for an accessible route and a bench.", "The council reviewed the proposal and assigned responsibilities for the school, residents, and public works team.")),
            StoryPart(7, "The Workday", listOf("Qualified workers repaired the path and gate. Volunteers helped plant approved garden beds on school property after the work area was declared safe.", "Yemi's art class designed signs showing the path's history and its opening hours. The signs included a contact for reporting maintenance problems.")),
            StoryPart(8, "A Walk with Permission", listOf("The council reopened the route after the final inspection. The first walk included residents, students, and the library manager, who explained how the path could help people reach services.", "The old resting place was not reopened because it still needed work, but the accessible section offered a useful connection between the streets.")),
            StoryPart(9, "The Garden Beside the Gate", listOf("The school garden team planted flowers chosen for local conditions and created a maintenance rota. The residents' group agreed to review the path every month.", "The library added a small display about the route's history, using copies of the original map and minutes.")),
            StoryPart(10, "A Connection Restored", listOf("At the opening, the retired secretary walked the path with Yemi and pointed out where neighbours once met. She said the new route was different, but it served the same purpose.", "The hidden gate had led to more than an old path. It had brought two groups together, clarified who was responsible for maintenance, and created a safer connection. Yemi added the restored route to the school's map, with the inspection date and access information clearly marked."))
        )),
        StorySeries("the_clockwork_bird", "The Clockwork Bird", "A small mechanical bird helps a young maker uncover the story of a community craft teacher.", listOf(
            StoryPart(1, "A Bird in the Window", listOf("At a charity book sale, Nosa noticed a tiny mechanical bird perched in the window. It moved its head when a visitor turned a brass key, then played three gentle notes.", "The seller said it had been donated with no information about its maker. A paper tag carried only the initials 'E.O.' and the year 1986.")),
            StoryPart(2, "The Maker's Mark", listOf("Nosa's technology teacher recognised the mark as belonging to a local craft cooperative. The cooperative had closed, but its former secretary might know who made the bird.", "The secretary remembered a craft teacher named Efe Okon, who taught young people to repair and reuse household objects.")),
            StoryPart(3, "The Workshop Photograph", listOf("A photograph showed Efe with a group of students holding small inventions. The bird appeared on a table, beside a notebook of mechanical sketches.", "The secretary explained that Efe had donated the bird to the community centre as a demonstration piece. The centre's records might reveal why it ended up at the book sale.")),
            StoryPart(4, "The Donation Trail", listOf("The community centre ledger showed that the bird had been loaned to a school exhibition, then returned during a storage clear-out. It was later donated when the centre changed management.", "Nosa contacted the school and found a copy of the original loan form, signed by Efe's former student.")),
            StoryPart(5, "The Student's Story", listOf("The former student, now an engineer, said Efe had taught repair skills to students who could not afford new equipment. The bird was designed to show how a simple mechanism could create movement and sound.", "She still had Efe's workshop notes and offered to bring them to the community centre for a display.")),
            StoryPart(6, "A Careful Repair", listOf("The bird's key mechanism had become stiff, so Nosa did not try to force it. A qualified clock repairer inspected it and explained which parts could be cleaned and adjusted safely.", "The repairer found a tiny maker's mark beneath the base, confirming that Efe had built it by hand.")),
            StoryPart(7, "The Workshop Notes", listOf("The notes described Efe's teaching approach: demonstrate a principle, let students ask questions, and always explain how to handle tools safely. They also listed students who had gone on to teach others.", "The community centre proposed a small annual craft workshop in Efe's name, with trained supervision and clear equipment rules.")),
            StoryPart(8, "The Bird Sings Again", listOf("After servicing, the bird played its three notes again. The centre displayed it beside the workshop notes and a photograph of Efe's students.", "Nosa helped prepare a simple explanation of the mechanism, making clear that the bird was a teaching model rather than a toy for unsupervised handling.")),
            StoryPart(9, "A New Class", listOf("The first workshop brought together young makers and former students. They learned about gears, balance, and careful repair using safe demonstration materials.", "The engineer shared stories about Efe's patience and encouraged students to document their work so future learners could build on it.")),
            StoryPart(10, "The Notes Continue", listOf("The centre established a yearly craft day and created a small archive of the cooperative's designs. The bird remained on display, with a copy of the repair record and its history.", "Nosa added a new page to the workshop notebook: 'A good invention does not end with its maker. It continues whenever someone learns from it.' The bird's origin was known, its creator was credited, and the craft lessons had found a new generation."))
        )),
        StorySeries("the_rainwater_roof", "The Rainwater Roof", "A science team investigates an old water collection system and designs a responsible community project.", listOf(
            StoryPart(1, "The Empty Tank", listOf("A school science team found a large empty tank beside the assembly hall. A faded sign said it had collected rainwater for the school garden.", "Their teacher explained that the system had been disconnected after a maintenance problem. The students were curious, but agreed not to touch the equipment until it had been inspected.")),
            StoryPart(2, "The Maintenance File", listOf("The school manager found a file describing the original system. It included a diagram, a cleaning schedule, and a note that the tank had been taken out of service after a damaged cover was discovered.", "The students asked a qualified plumber to assess the tank and pipework before considering any reuse.")),
            StoryPart(3, "The Plumber's Report", listOf("The plumber found that the tank needed cleaning, a secure cover, and replacement fittings. The report also recommended clear labels so nobody mistook collected rainwater for drinking water.", "The school agreed that any future use would be limited to approved non-drinking purposes and would follow local health and safety guidance.")),
            StoryPart(4, "The Garden's Needs", listOf("The gardening club explained that its plants needed regular watering during dry weeks. The science team measured the garden area and estimated how much water the project might reasonably collect.", "Their teacher reminded them that rainfall varied and the project should never promise a supply it could not guarantee.")),
            StoryPart(5, "The Budget Meeting", listOf("The students prepared a budget for repairs, filters appropriate to the intended use, secure covers, and maintenance checks. The school board reviewed the plan and approved only the inspected system.", "A local environmental group offered to teach the students about water conservation and responsible collection.")),
            StoryPart(6, "A Safe Demonstration", listOf("After the plumber completed the work, the school tested the system under supervision. The students observed how rainwater moved from the approved collection surface into the tank.", "They recorded the date, rainfall, and tank level, and placed clear signs stating that the water was not for drinking.")),
            StoryPart(7, "A Dry Month", listOf("A month with little rain showed that the system could not meet every garden need. The club adjusted its plan to use collected water carefully and continued other conservation measures.", "The students documented the limits honestly. They learned that good science includes recording what a system cannot do.")),
            StoryPart(8, "The Open Lesson", listOf("The science team hosted a lesson for younger classes, explaining the tank, the maintenance schedule, and why clear labels mattered. The plumber answered questions about inspections.", "The gardening club demonstrated how it prioritised watering and used mulch to reduce waste.")),
            StoryPart(9, "The Maintenance Handover", listOf("Before the graduating students left, they created a handover file with inspection dates, responsible adults, and instructions for reporting problems. The school manager agreed to review the system each term.", "The environmental group added a simple water-conservation lesson to the school's annual programme.")),
            StoryPart(10, "A Resource Used Wisely", listOf("At the end of the year, the tank had supported the garden during several dry periods, though it was never treated as a guaranteed supply. The school kept the maintenance records and labels in place.", "The students' project won recognition for careful planning rather than dramatic claims. They had restored a useful resource, respected its limits, and left a system that the next class could manage responsibly."))
        )),
        StorySeries("the_post_office_window", "The Post Office Window", "A closed service window inspires a student to help residents access reliable information and support.", listOf(
            StoryPart(1, "The Window That Stayed Shut", listOf("A post office had a small side window that had been closed for years. Fara noticed an old sign saying it once offered help with forms for residents who needed assistance.", "The postmaster explained that the service had moved online, but some residents still found the forms difficult to understand.")),
            StoryPart(2, "A Box of Guides", listOf("The post office archive contained printed guides from the old service. They were outdated, but showed which questions people commonly asked about deliveries and official forms.", "Fara's civic studies teacher suggested that any new guide should be checked by the relevant agencies and should never collect private information unnecessarily.")),
            StoryPart(3, "The Community Survey", listOf("Students asked residents which services were hardest to understand. Many wanted clearer instructions, larger print, and a place to ask general questions without sharing sensitive details.", "The class summarised the responses anonymously and sent them to the post office manager.")),
            StoryPart(4, "The Official Contacts", listOf("The manager provided a list of current official websites and phone contacts for each service. The students checked that the links were correct and asked permission before displaying them.", "They discovered that several printed guides still contained old addresses. Those were removed from circulation.")),
            StoryPart(5, "A New Information Board", listOf("The post office approved a public information board with current opening hours, official service contacts, and simple instructions for common non-sensitive tasks.", "The board included a date for review and a note telling residents not to leave passwords, account details, or original documents in the public area.")),
            StoryPart(6, "The Reading Volunteers", listOf("A local literacy group offered volunteers to help residents understand public information. The post office arranged a separate desk and clear appointment times.", "The volunteers received guidance on privacy and were instructed to refer legal, financial, or identity-specific questions to the appropriate official service.")),
            StoryPart(7, "A Busy First Day", listOf("On the first day, several residents asked for help locating forms and understanding instructions. The volunteers explained where to find official information but did not fill in private answers for people.", "The manager reviewed the process at closing time and adjusted the queue so residents could ask general questions discreetly.")),
            StoryPart(8, "A Guide in Three Formats", listOf("The class produced a large-print guide, a simple-language version, and an audio explanation. The post office checked all three before making them available.", "A resident suggested adding a list of translation support services. The students verified the contacts and added them with permission.")),
            StoryPart(9, "Keeping Information Current", listOf("The post office assigned a staff member to review the board each month. The class created a simple change log so outdated details could be removed promptly.", "The literacy group agreed to provide feedback, while the students learned that public information needed regular maintenance.")),
            StoryPart(10, "A Window Reopened in Spirit", listOf("The side window did not reopen as a separate official counter, but the post office established a weekly information session with trained volunteers and clear privacy boundaries.", "Fara looked at the new board and understood the real achievement: residents had a reliable way to find help without being misled or exposing private details. The service had changed form, but its purpose—making information easier to reach—had returned."))
        ))
    )
}
